import forge.ai.*;
import forge.ai.bridge.*;
import forge.deck.Deck;
import forge.game.*;
import forge.game.card.*;
import forge.game.player.*;
import forge.game.phase.*;
import forge.game.zone.*;
import com.google.gson.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

/** Native paid activation and search; rejects forged copy lineage. */
public class MistySearchReplayRegression extends AITest {
 static JsonArray ids(Iterable<Card> cards,boolean sort){List<Integer> list=new ArrayList<>();cards.forEach(c->list.add(c.getId()));if(sort)Collections.sort(list);JsonArray out=new JsonArray();list.forEach(out::add);return out;}
 static JsonObject row(int index,String type,String hook,Player p){JsonObject out=new JsonObject();out.addProperty("kind","decision");out.addProperty("index",index);out.addProperty("decision_type",type);out.addProperty("hook",hook);out.addProperty("actor_id",p.getId());return out;}
 public static void main(String[] args)throws Exception{
  String mode=args[0];Path dir=Path.of(args[1]);Files.createDirectories(dir);System.setProperty("forge.audit.directory",dir.resolve("audit").toString());var test=new MistySearchReplayRegression();test.initializeModel();test.initAndCreateGame();List<RegisteredPlayer> seats=new ArrayList<>();for(int i=0;i<4;i++)seats.add(new RegisteredPlayer(new Deck()).setPlayer(new LobbyPlayerAi("seat"+i,null)));var rules=new GameRules(GameType.Commander);Game game=new Game(seats,rules,new Match(rules,seats,"Misty search"));Player p=game.getPlayers().get(0);game.setAge(GameStage.Play);game.getPhaseHandler().devModeSet(PhaseType.MAIN1,p,false);game.getPhaseHandler().setPriority(p);Card forest=test.addCardToZone("Forest",p,ZoneType.Library),island=test.addCardToZone("Island",p,ZoneType.Library),mountain=test.addCardToZone("Mountain",p,ZoneType.Library),card=test.addCardToZone("Misty Rainforest",p,ZoneType.Battlefield);var ability=card.getSpellAbilities().stream().filter(sa->"ChangeZone".equals(String.valueOf(sa.getApi()))).findFirst().orElseThrow();ability.setActivatingPlayer(p);int life=p.getLife();JsonObject params=new JsonObject();ability.getMapParams().forEach(params::addProperty);
  JsonObject choose=row(0,"misty_activation","forge/ai/bridge/PlayerControllerBridge.chooseSpellAbilityToPlay()Ljava/util/List;",p);choose.addProperty("source_card_id",card.getId());choose.addProperty("original_ability_id",ability.getId()+500);choose.add("ability_parameters",params.deepCopy());JsonObject context=new JsonObject();context.addProperty("turn",game.getPhaseHandler().getTurn());context.addProperty("phase","MAIN1");context.addProperty("priority_player_id",p.getId());context.addProperty("turn_player_id",p.getId());choose.add("context",context);
  JsonObject pay=row(1,"misty_zero_component","forge/game/player/PlayerController.payManaCost(Lforge/game/cost/CostPartMana;Lforge/game/spellability/SpellAbility;Ljava/lang/String;Lforge/game/mana/ManaConversionMatrix;Z)Z",p);pay.addProperty("source_ability",card.getId()+":"+(ability.getId()+500));pay.addProperty("ability_api","ChangeZone");pay.add("ability_parameters",params.deepCopy());
  JsonObject search=row(2,"misty_library_choice","forge/ai/bridge/PlayerControllerBridge.chooseSingleCardForZoneChange(Lforge/game/zone/ZoneType;Ljava/util/List;Lforge/game/spellability/SpellAbility;Lforge/game/card/CardCollection;Lforge/game/player/DelayedReveal;Ljava/lang/String;ZLforge/game/player/Player;)Lforge/game/card/Card;",p);search.addProperty("source_ability",card.getId()+":"+(ability.getId()+900));search.addProperty("ability_api","ChangeZone");search.add("ability_parameters",params.deepCopy());search.add("available_card_ids",ids(List.of(forest,island),true));search.addProperty("selected_card_id",mode.equals("invalid")?999999:forest.getId());search.addProperty("title","Select a card from your library");search.addProperty("reveal_owner_id",p.getId());search.add("reveal_card_ids",ids(p.getCardsIn(ZoneType.Library),false));search.addProperty("reveal_message","Misty Rainforest - Looking at cards in ");
  Path input=dir.resolve("decisions.jsonl");Files.writeString(input,choose+"\n"+pay+"\n"+search+"\n{\"kind\":\"decision_tape_complete\",\"decisions\":3}\n",StandardOpenOption.CREATE_NEW);System.setProperty("forge.decision.replayTape",input.toString());System.setProperty("forge.decision.replaySha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(input))));System.setProperty("forge.decision.replayDiagnostics",dir.resolve("diagnostics").toString());DurableEvidence.begin("misty-search-fixture");EngineEvidence.begin(game);
  p.getController().chooseSpellAbilityToPlay();if(!ComputerUtil.handlePlayingSpellAbility(p,ability,null))throw new AssertionError("Actual activation failed");
  try{
   if(mode.equals("impostor")){var copy=game.getStack().peekAbility().copy();copy.setOriginalAbility(null);p.getController().chooseSingleCardForZoneChange(ZoneType.Battlefield,List.of(ZoneType.Library),copy,new CardCollection(List.of(forest,island)),new DelayedReveal(p.getCardsIn(ZoneType.Library),Set.of(ZoneType.Library),p.getView(),"Misty Rainforest - Looking at cards in "),"Select a card from your library",true,p);}else game.getStack().resolveStack();
   if(!mode.equals("valid"))throw new AssertionError("Invalid search accepted");if(!game.getCardState(forest).isInZone(ZoneType.Battlefield)||game.getCardState(forest).isTapped()||!game.getCardState(card).isInZone(ZoneType.Graveyard)||p.getLife()!=life-1||p.getCardsIn(ZoneType.Library).size()!=2||!island.isInZone(ZoneType.Library)||!mountain.isInZone(ZoneType.Library))throw new AssertionError("Native fetch resolution differs");DecisionReplay.finish();EngineEvidence.finish();JsonObject result=new JsonObject();result.addProperty("seed",114);result.addProperty("status","completed");DurableEvidence.finish(dir.resolve("results"),114,"fetch-only fixture\nDragonMind Result: "+result+"\n",result);System.out.println("PASS paid native stack-copy search, private look, Forest move and shuffle; no complete game claim");
  }catch(IllegalStateException error){String expected=mode.equals("invalid")?"Unavailable Misty search":"no exact paid activation";if(mode.equals("valid")||!error.getMessage().contains(expected))throw error;if(!forest.isInZone(ZoneType.Library)||!island.isInZone(ZoneType.Library))throw new AssertionError("Rejected search moved a land");System.out.println("PASS "+mode+" search rejected without selected-card zone mutation; activation costs remain paid");}
  System.exit(0);
 }
}
